    {

           using var activity =  StartCallActivity("SaveApplicationLogEventAsync", typeof(SaveApplicationLogEvent).FullName ?? "SaveApplicationLogEventAsync");

           try
           {
             return client.SaveApplicationLogEventAsync(type, chatId, data);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
